update benefits set faq = '[{"question": "나이는 만 나이 기준인가요?", "answer": "네, 만 24세를 기준으로 하며 통상 공고일 또는 신청일 기준으로 계산합니다. 정확한 기준일은 공식 공고문에서 다시 확인하세요."}, {"question": "상시 신청이 가능한가요?", "answer": "네, 이 제도는 특별한 마감 없이 상시 신청할 수 있습니다. 다만 예산이 소진되면 조기 마감될 수 있으니 가능한 한 빨리 신청하는 것이 좋습니다."}, {"question": "신청할 때 어떤 서류가 필요한가요?", "answer": "신분증(본인 확인용), 주민등록초본(마이데이터 미동의 시) 등이 필요합니다. 정확한 서류 목록은 신청 전 공식 안내에서 다시 확인하세요."}]'::jsonb where slug = 'gyeonggi-basic-income-youth-2025';
