update benefits set faq = '[{"question": "소득 기준은 어떻게 확인하나요?", "answer": "기초생활수급자·차상위계층 등 취약계층 기준 조건을 충족해야 합니다. 정확한 소득 산정 방식은 복지로 모의계산이나 담당 기관에 문의해 확인하는 것이 안전합니다."}, {"question": "상시 신청이 가능한가요?", "answer": "네, 이 제도는 특별한 마감 없이 상시 신청할 수 있습니다. 다만 예산이 소진되면 조기 마감될 수 있으니 가능한 한 빨리 신청하는 것이 좋습니다."}, {"question": "신청할 때 어떤 서류가 필요한가요?", "answer": "산모수첩 또는 임신확인서(임신 중 신청 시), 출생신고 관련 서류(출산 후 신청 시), 취약계층 증빙서류, 부모교육 이수 확인서 등이 필요합니다. 정확한 서류 목록은 신청 전 공식 안내에서 다시 확인하세요."}]'::jsonb where slug = 'incheon-postpartum-care-support-2025';
update benefits set faq = '[{"question": "소득 기준은 어떻게 확인하나요?", "answer": "본인부담금 90% 지원은 수급자·차상위계층 기준 (바우처 자체는 소득 무관) 조건을 충족해야 합니다. 정확한 소득 산정 방식은 복지로 모의계산이나 담당 기관에 문의해 확인하는 것이 안전합니다."}, {"question": "상시 신청이 가능한가요?", "answer": "네, 이 제도는 특별한 마감 없이 상시 신청할 수 있습니다. 다만 예산이 소진되면 조기 마감될 수 있으니 가능한 한 빨리 신청하는 것이 좋습니다."}, {"question": "신청할 때 어떤 서류가 필요한가요?", "answer": "산모수첩 또는 출생신고 서류, 주민등록등본, 수급자·차상위 증빙서류(해당 시) 등이 필요합니다. 정확한 서류 목록은 신청 전 공식 안내에서 다시 확인하세요."}]'::jsonb where slug = 'seoul-maternal-newborn-care';
update benefits set faq = '[{"question": "소득 기준은 어떻게 확인하나요?", "answer": "부부합산 기준 중위소득 180% 이하 조건을 충족해야 합니다. 정확한 소득 산정 방식은 복지로 모의계산이나 담당 기관에 문의해 확인하는 것이 안전합니다."}, {"question": "신혼부부가 아니어도 신청할 수 있나요?", "answer": "이 제도는 신혼부부를 기준으로 하므로 해당 요건을 충족해야 신청할 수 있습니다. 정확한 판단 기준은 담당 기관에 문의하세요."}, {"question": "상시 신청이 가능한가요?", "answer": "네, 이 제도는 특별한 마감 없이 상시 신청할 수 있습니다. 다만 예산이 소진되면 조기 마감될 수 있으니 가능한 한 빨리 신청하는 것이 좋습니다."}]'::jsonb where slug = 'gyeonggi-newlywed-jeonse-loan-interest';
update benefits set faq = '[{"question": "상시 신청이 가능한가요?", "answer": "네, 이 제도는 특별한 마감 없이 상시 신청할 수 있습니다. 다만 예산이 소진되면 조기 마감될 수 있으니 가능한 한 빨리 신청하는 것이 좋습니다."}, {"question": "신청할 때 어떤 서류가 필요한가요?", "answer": "출생신고 관련 서류, 주민등록등본 등이 필요합니다. 정확한 서류 목록은 신청 전 공식 안내에서 다시 확인하세요."}, {"question": "다른 지원금과 중복으로 받을 수 있나요?", "answer": "제도별로 중복 수혜 가능 여부가 다릅니다. 경기도 인구정책과에 문의해 다른 지원금과 함께 받을 수 있는지 확인하는 것이 안전합니다."}]'::jsonb where slug = 'gyeonggi-postpartum-care-support';
update benefits set faq = '[{"question": "소득 기준은 어떻게 확인하나요?", "answer": "청년 5천만원 이하 / 청년 외 6천만원 이하 / 신혼부부 7천5백만원 이하 조건을 충족해야 합니다. 정확한 소득 산정 방식은 복지로 모의계산이나 담당 기관에 문의해 확인하는 것이 안전합니다."}, {"question": "상시 신청이 가능한가요?", "answer": "네, 이 제도는 특별한 마감 없이 상시 신청할 수 있습니다. 다만 예산이 소진되면 조기 마감될 수 있으니 가능한 한 빨리 신청하는 것이 좋습니다."}, {"question": "신청할 때 어떤 서류가 필요한가요?", "answer": "전세보증금 반환보증 가입 증서, 보증료 납부 영수증, 임대차계약서, 소득 증빙서류 등이 필요합니다. 정확한 서류 목록은 신청 전 공식 안내에서 다시 확인하세요."}]'::jsonb where slug = 'gyeonggi-jeonse-guarantee-fee-support';
update benefits set faq = '[{"question": "소득 기준은 어떻게 확인하나요?", "answer": "부부합산 연소득 8천만원 이하 조건을 충족해야 합니다. 정확한 소득 산정 방식은 복지로 모의계산이나 담당 기관에 문의해 확인하는 것이 안전합니다."}, {"question": "신혼부부가 아니어도 신청할 수 있나요?", "answer": "이 제도는 신혼부부를 기준으로 하므로 해당 요건을 충족해야 신청할 수 있습니다. 정확한 판단 기준은 담당 기관에 문의하세요."}, {"question": "상시 신청이 가능한가요?", "answer": "네, 이 제도는 특별한 마감 없이 상시 신청할 수 있습니다. 다만 예산이 소진되면 조기 마감될 수 있으니 가능한 한 빨리 신청하는 것이 좋습니다."}]'::jsonb where slug = 'incheon-newlywed-jeonse-loan-interest';
update benefits set faq = '[{"question": "상시 신청이 가능한가요?", "answer": "네, 이 제도는 특별한 마감 없이 상시 신청할 수 있습니다. 다만 예산이 소진되면 조기 마감될 수 있으니 가능한 한 빨리 신청하는 것이 좋습니다."}, {"question": "신청할 때 어떤 서류가 필요한가요?", "answer": "전세보증금 반환보증 가입 증서, 보증료 납부 영수증, 임대차계약서 등이 필요합니다. 정확한 서류 목록은 신청 전 공식 안내에서 다시 확인하세요."}, {"question": "다른 지원금과 중복으로 받을 수 있나요?", "answer": "제도별로 중복 수혜 가능 여부가 다릅니다. 인천시 주택정책과에 문의해 다른 지원금과 함께 받을 수 있는지 확인하는 것이 안전합니다."}]'::jsonb where slug = 'incheon-jeonse-guarantee-fee-support';
update benefits set faq = '[{"question": "나이는 만 나이 기준인가요?", "answer": "네, 만 18~39세를 기준으로 하며 통상 공고일 또는 신청일 기준으로 계산합니다. 정확한 기준일은 공식 공고문에서 다시 확인하세요."}, {"question": "언제든지 신청할 수 있나요?", "answer": "아니요, 이 제도는 연중 특정 기간에만 신청을 받습니다. 정확한 신청 기간은 인천시 청년정책담당관 공고를 통해 확인해야 합니다."}, {"question": "신청할 때 어떤 서류가 필요한가요?", "answer": "신분증, 구직활동 증빙서류, 병역관련 서류(해당 시) 등이 필요합니다. 정확한 서류 목록은 신청 전 공식 안내에서 다시 확인하세요."}]'::jsonb where slug = 'incheon-dream-check-card';
update benefits set faq = '[{"question": "소득 기준은 어떻게 확인하나요?", "answer": "청년가구 중위소득 60% 이하 & 원가구 중위소득 100% 이하 조건을 충족해야 합니다. 정확한 소득 산정 방식은 복지로 모의계산이나 담당 기관에 문의해 확인하는 것이 안전합니다."}, {"question": "나이는 만 나이 기준인가요?", "answer": "네, 만 19~34세를 기준으로 하며 통상 공고일 또는 신청일 기준으로 계산합니다. 정확한 기준일은 공식 공고문에서 다시 확인하세요."}, {"question": "1인가구가 아니어도 신청할 수 있나요?", "answer": "이 제도는 1인가구를 기준으로 하므로 해당 요건을 충족해야 신청할 수 있습니다. 정확한 판단 기준은 담당 기관에 문의하세요."}]'::jsonb where slug = 'gangnam-youth-rent-support';
