update benefits set faq = '[{"question": "나이는 만 나이 기준인가요?", "answer": "네, 만 19~34세를 기준으로 하며 통상 공고일 또는 신청일 기준으로 계산합니다. 정확한 기준일은 공식 공고문에서 다시 확인하세요."}, {"question": "1인가구가 아니어도 신청할 수 있나요?", "answer": "이 제도는 1인가구를 기준으로 하므로 해당 요건을 충족해야 신청할 수 있습니다. 정확한 판단 기준은 담당 기관에 문의하세요."}, {"question": "언제든지 신청할 수 있나요?", "answer": "아니요, 이 제도는 연중 특정 기간에만 신청을 받습니다. 정확한 신청 기간은 광주시 청년정책담당관 공고를 통해 확인해야 합니다."}]'::jsonb where slug = 'gwangju-youth-rent-support';
